<template>
  <div v-if="canImport || canExport" class="master-transfer">
    <el-button v-if="canImport" plain :disabled="externalBusy" @click="opened=true">{{t('批量导入','Bulk import')}}</el-button>
    <el-button v-if="canExport" plain :disabled="externalBusy" @click="exportOpened=true">{{t('导出 Excel','Export Excel')}}</el-button>
    <el-alert v-if="pending || pendingError" type="warning" :closable="false" class="pending"><template #title>{{pendingError || t('导入结果尚未确认，请恢复原请求。','Import outcome is unconfirmed. Recover the original request.')}}</template><el-button v-if="pending" :loading="busy" @click="send(true)">{{t('重试原导入请求','Retry original import request')}}</el-button></el-alert>
    <el-drawer v-model="opened" :title="t('主数据批量导入','Bulk master data import')" size="min(1000px,100%)" :close-on-click-modal="!busy" :close-on-press-escape="!busy" :show-close="!busy">
      <el-alert v-if="error" type="error" :title="error" :closable="false" />
      <p class="help">{{t('先预检，再确认写入。任意一行出错，整批都不会写入。每批最多 500 行、2 MiB，支持 XLSX 和 UTF-8 CSV。','Preview before committing. If any row fails, the whole batch stays unchanged. Up to 500 rows and 2 MiB per batch; XLSX and UTF-8 CSV are supported.')}}</p>
      <el-form label-position="top" :disabled="blocked || externalBusy" @submit.prevent="preview">
        <el-form-item :label="t('导入方式','Import mode')"><el-select v-model="mode" :aria-label="t('导入方式','Import mode')" style="width:250px"><el-option v-if="canAdd" value="create" :label="t('新增资料','Create records')" /><el-option v-if="canEdit" value="update" :label="t('更新已有资料','Update existing records')" /></el-select></el-form-item>
        <p class="help">{{t('更新须保留导出文件中的 id 和 _version。空单元格保留原值或默认值；要清空字段请填 __CLEAR__。关联资料可填编号或权限范围内唯一名称。条码、日期和编号请用文本单元格。','Updates require id and _version from the export. Empty cells preserve defaults or existing values; use __CLEAR__ to clear a field. References accept an ID or a unique visible name. Keep barcodes, dates and identifiers as text cells.')}}</p>
        <div class="upload-actions"><el-button :disabled="!mode" @click="download(true)">{{t('下载此方式模板','Download template for this mode')}}</el-button><div class="file-label"><span>{{t('导入文件','Import file')}}</span><el-button @click="fileInput?.click()">{{t('选择文件','Choose file')}}</el-button><span class="chosen-file">{{file?.name || t('尚未选择文件','No file selected')}}</span><input ref="fileInput" class="native-file" type="file" accept=".xlsx,.csv" :disabled="blocked || externalBusy" :aria-label="t('导入文件','Import file')" @change="choose" /></div><el-button type="primary" :disabled="!file || !mode" :loading="busy" @click="preview">{{t('开始预检','Preview import')}}</el-button></div>
      </el-form>
      <section v-if="detail" class="preview">
        <h3>{{detail.fileName}}</h3><p>{{detail.mode==='create'?t('新增资料','Create records'):t('更新已有资料','Update existing records')}} · {{statusLabel(detail.status)}} · {{t('通过预检行数','Validated rows')}}: {{detail.count}} · {{t('错误行数','Row errors')}}: {{detail.errors?.length || 0}}</p>
        <el-alert v-if="!detail.valid" type="error" :closable="false" :title="t('预检未通过，尚未写入任何主数据。请修改文件后重新预检。','Preview failed. No master data was written. Correct the file and preview again.')" />
        <el-table v-if="detail.errors?.length" :data="detail.errors" border><el-table-column prop="row" :label="t('文件行号','File row')" width="115" /><el-table-column prop="message" :label="t('问题','Problem')" min-width="300" /></el-table>
        <el-table :data="previewRows" border class="preview-table"><el-table-column type="expand"><template #default="{row}"><el-table :data="importChanges(row)" border><el-table-column :label="t('字段','Field')" min-width="160"><template #default="{row:change}">{{fieldLabel(change.key)}}</template></el-table-column><el-table-column prop="before" :label="t('原值','Before')" min-width="170" /><el-table-column prop="after" :label="t('导入后','After')" min-width="170" /></el-table></template></el-table-column><el-table-column prop="row" :label="t('文件行号','File row')" width="115" /><el-table-column :label="t('资料','Record')" min-width="200"><template #default="{row}">{{row.after.sku || row.after.shortName || row.after.name}}</template></el-table-column><el-table-column :label="t('变更字段','Changed fields')" min-width="220"><template #default="{row}">{{row.changed.slice(0,3).map(fieldLabel).join('、')}}{{row.changed.length>3?'…':''}} ({{row.changed.length}})</template></el-table-column></el-table>
        <pagination v-if="detail.count>20" :total="detail.count" v-model:page="previewPage" :limit="20" :page-sizes="[20]" />
        <div v-if="detail.status==='PREVIEW'" class="actions"><el-button :disabled="blocked" @click="act(detail,'cancel')">{{t('撤销此预检','Cancel this preview')}}</el-button><el-button type="primary" :disabled="blocked || !canWriteMode(detail.mode)" @click="act(detail,'commit')">{{t('确认导入','Commit import')}} {{detail.count}} {{t('行','rows')}}</el-button></div>
        <el-alert v-if="detail.status==='COMMITTED'" type="success" :closable="false" :title="t('整批导入已完成，主数据列表已更新。','The complete batch was imported. The master data list has been refreshed.')" />
      </section>
      <section class="history"><h3>{{t('我的最近导入','My recent imports')}}</h3><el-button :disabled="busy" @click="loadHistory">{{t('刷新导入记录','Refresh import history')}}</el-button><el-table :data="history" border :empty-text="t('尚无通过预检的文件','No validated imports yet')"><el-table-column prop="fileName" :label="t('文件','File')" min-width="180" /><el-table-column prop="count" :label="t('行数','Rows')" width="80" /><el-table-column :label="t('状态','Status')" min-width="150"><template #default="{row}">{{statusLabel(row.status)}}</template></el-table-column><el-table-column min-width="170"><template #default="{row}"><el-button link type="primary" :disabled="blocked" @click="read(row.id)">{{t('查看预检','View preview')}}</el-button><el-button v-if="row.status==='PREVIEW'" link type="danger" :disabled="blocked" @click="act(row,'cancel')">{{t('撤销','Cancel')}}</el-button></template></el-table-column></el-table></section>
    </el-drawer>
    <el-dialog v-model="exportOpened" :title="t('导出 Excel','Export Excel')" width="min(520px,94vw)"><el-alert v-if="error" :title="error" type="error" :closable="false" /><p class="help">{{t('沿用当前关键词筛选，每份最多 500 行，可选择批次逐份下载。导出只包含你有权查看的资料和字段。','Uses the current keyword filter. Download up to 500 rows per file and choose a batch for larger lists. Only authorized records and fields are exported.')}}</p><el-form label-position="top"><el-form-item :label="t('关键词','Keyword')"><span>{{keyword || t('全部','All')}}</span></el-form-item><el-form-item :label="t('导出批次','Export batch')"><el-input-number v-model="exportPage" :min="1" :max="Math.max(1,Math.ceil(total/500))" :precision="0" :aria-label="t('导出批次','Export batch')" /><span class="batch-total">/ {{Math.max(1,Math.ceil(total/500))}}</span></el-form-item></el-form><template #footer><el-button @click="exportOpened=false">{{t('关闭','Close')}}</el-button><el-button type="primary" :loading="downloading" @click="download(false)">{{t('下载本批次','Download this batch')}}</el-button></template></el-dialog>
  </div>
</template>
<script setup>
import { ref, computed, onMounted, watch } from 'vue'
import { ElMessageBox } from 'element-plus'
import { saveAs } from 'file-saver'
import auth from '@/plugins/auth'
import request from '@/utils/request'
import useUserStore from '@/store/modules/user'
import { bilingual as t } from '@/warehouse/i18n'
import { rejectedBeforeCommit } from '@/warehouse/inventory'
import { importPendingKey, readImportPending, importFileProblem, importChanges } from '@/warehouse/master-transfer'
const props=defineProps({kind:String,fields:Array,keyword:String,total:Number,externalBusy:Boolean}),emit=defineEmits(['changed','blocked']),user=useUserStore()
const allowed=action=>auth.hasPermi('warehouse:'+props.kind+':'+action),canImport=computed(()=>allowed('import')&&(!['suppliers','channels'].includes(props.kind)||Number(user.id)===1)),canExport=computed(()=>allowed('export')&&allowed('list')&&allowed('query')),canAdd=computed(()=>allowed('add')),canEdit=computed(()=>allowed('edit')&&allowed('query')),canWriteMode=value=>value==='create'?canAdd.value:canEdit.value
const base=computed(()=>'/warehouse/master/'+props.kind),opened=ref(false),exportOpened=ref(false),mode=ref(canAdd.value?'create':canEdit.value?'update':''),file=ref(null),fileInput=ref(null),busy=ref(false),downloading=ref(false),error=ref(''),history=ref([]),detail=ref(null),previewPage=ref(1),exportPage=ref(1),pending=ref(null),pendingError=ref('')
const blocked=computed(()=>busy.value||!!pending.value||!!pendingError.value),previewRows=computed(()=>(detail.value?.rows||[]).slice((previewPage.value-1)*20,previewPage.value*20)),fieldLabel=key=>{const field=props.fields?.find(f=>f.key===key);return field?t(field.label,field.labelEn):key}
const statusLabel=value=>t(({PREVIEW:'待确认写入',COMMITTED:'已导入',CANCELLED:'已撤销'})[value]||'预检结果',({PREVIEW:'Ready to commit',COMMITTED:'Imported',CANCELLED:'Cancelled'})[value]||'Preview result')
function choose(event){file.value=event.target.files?.[0]||null;detail.value=null;error.value=''}
async function loadHistory(){if(!canImport.value)return;try{history.value=(await request({url:base.value+'/imports'})).data.rows}catch(e){error.value=e.message}}
async function read(id){if(busy.value)return;busy.value=true;error.value='';try{detail.value=(await request({url:base.value+'/imports/'+id})).data;previewPage.value=1}catch(e){error.value=e.message}finally{busy.value=false}}
async function preview(){if(blocked.value)return;const issue=importFileProblem(file.value);if(issue){error.value=issue==='file_type'?t('请选择 XLSX 或 CSV 文件。','Choose an XLSX or CSV file.'):t('文件不能为空，且不能超过 2 MiB。','The file must be nonempty and no larger than 2 MiB.');return}busy.value=true;error.value='';detail.value=null;try{const data=new FormData();data.append('mode',mode.value);data.append('file',file.value);detail.value=(await request({url:base.value+'/imports/preview',method:'post',data,headers:{'Content-Type':'multipart/form-data',repeatSubmit:false},timeout:120000})).data;previewPage.value=1;await loadHistory()}catch(e){error.value=e.message}finally{busy.value=false}}
async function act(row,action){if(blocked.value)return;try{await ElMessageBox.confirm(action==='commit'?t('确认按预检结果写入这批资料？关联资料或版本变化时，整批将拒绝写入。','Commit this preview? Changed references or versions will reject the complete batch.'):t('撤销此预检？不会删除任何主数据。','Cancel this preview? No master records will be deleted.'),t('确认操作','Confirm operation'),{type:'warning',confirmButtonText:t('确认','Confirm'),cancelButtonText:t('返回','Back')})}catch{return}if(blocked.value)return;const value={kind:props.kind,id:row.id,payload:{requestId:crypto.randomUUID(),_version:row._version,action}};try{sessionStorage.setItem(importPendingKey(user.id,props.kind),JSON.stringify(value))}catch{pendingError.value=t('无法保存请求记录，尚未提交。','Could not save the request record. Nothing was submitted.');return}pending.value=value;await send(false)}
async function send(retrying){if(busy.value||!pending.value||!canImport.value)return;busy.value=true;error.value='';const value=pending.value;try{const response=await request({url:base.value+'/imports/'+value.id+'/actions',method:'post',data:value.payload,headers:{repeatSubmit:false},timeout:120000});sessionStorage.removeItem(importPendingKey(user.id,props.kind));pending.value=null;pendingError.value='';detail.value=response.data;previewPage.value=1;await loadHistory();if(detail.value.status==='COMMITTED')emit('changed')}catch(e){if(!retrying&&rejectedBeforeCommit(e)){sessionStorage.removeItem(importPendingKey(user.id,props.kind));pending.value=null;error.value=e.message}else error.value=(e.message||'')+' · '+t('结果尚未确认，请重试原请求。','The outcome is unconfirmed. Retry the original request.')}finally{busy.value=false}}
async function download(template){if(downloading.value)return;downloading.value=true;error.value='';try{const blob=await request({url:base.value+'/workbook',params:{template,mode:mode.value||'create',page:exportPage.value,size:500,keyword:template?'':props.keyword},responseType:'blob',timeout:120000});if(blob.type.includes('json')){const data=JSON.parse(await blob.text());throw Error(data.msg)}saveAs(blob,props.kind+(template?'-template':'-export-'+exportPage.value)+'.xlsx')}catch(e){error.value=e.message}finally{downloading.value=false}}
watch(blocked,value=>emit('blocked',value),{immediate:true})
watch(mode,()=>{detail.value=null;previewPage.value=1;error.value=''})
watch(()=>props.keyword,()=>{exportPage.value=1})
onMounted(()=>{try{pending.value=readImportPending(sessionStorage,user.id,props.kind)}catch{pendingError.value=t('本地请求记录损坏，请先核对导入历史，避免重复提交。','The local request record is damaged. Check import history before another submission.')}loadHistory()})
</script>
<style scoped>
.master-transfer{display:inline-block;margin-left:12px;max-width:100%}.help{line-height:1.65;max-width:75ch;text-align:left}.upload-actions,.actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:16px 0}.upload-actions .el-button,.actions .el-button{margin-left:0}.file-label{display:flex;gap:8px;flex-direction:column;max-width:100%}.chosen-file{max-width:250px;overflow-wrap:anywhere;font-size:13px}.native-file{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.preview,.history{margin-top:28px;min-width:0}.preview-table{margin:18px 0}.el-alert{margin-bottom:16px}.pending{margin-top:12px}.batch-total{margin-left:12px}h3{font-size:16px;overflow-wrap:anywhere}.history .el-table{margin-top:12px}@media(max-width:600px){.master-transfer{margin:12px 0 0;display:block}.upload-actions{align-items:stretch;flex-direction:column}}
</style>
